-- Part 23.02: the account of goods received not invoiced (template and every company's chart that has none), the flag, the pages, the page tracker,
-- the notification templates and the default posting rules (FR-06) as template rules from 01-04-2026 (a company's own change of a rule is a new version, approved).
INSERT INTO fin_accounts (company_id, group_id, code, name, account_type, normal_side, currency_code, is_control, control_kind, manual_posting_allowed, created_by, source_type)
  SELECT NULL, a.group_id, '240002', 'Goods received not invoiced', 'GENERAL', 'CR', 'INR', 0, NULL, 0, 'migration', 'fin_p2302' FROM fin_accounts a WHERE a.company_id IS NULL AND a.code = '240001' AND a.deleted_at IS NULL
  AND NOT EXISTS (SELECT 1 FROM fin_accounts x WHERE x.company_id IS NULL AND x.code = '240002');
INSERT INTO fin_accounts (company_id, group_id, code, name, account_type, normal_side, currency_code, is_control, control_kind, manual_posting_allowed, created_by, source_type)
  SELECT a.company_id, a.group_id, '240002', 'Goods received not invoiced', 'GENERAL', 'CR', 'INR', 0, NULL, 0, 'migration', 'fin_p2302' FROM fin_accounts a WHERE a.company_id IS NOT NULL AND a.code = '240001' AND a.deleted_at IS NULL
  AND NOT EXISTS (SELECT 1 FROM fin_accounts x WHERE x.company_id = a.company_id AND x.code = '240002');
